import hmac
import hashlib
import json
import time
import os
import re
from http.server import HTTPServer, BaseHTTPRequestHandler

SECRET_KEY = os.environ.get('HMAC_SECRET', os.urandom(32).hex())

def b64url_encode(data: bytes) -> str:
    import base64
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')

def b64url_decode(s: str) -> bytes:
    """RFC 7515 compliant base64url decoding with padding recovery."""
    s = s.strip()
    # Add padding characters as needed
    remainder = len(s) % 4
    if remainder == 2:
        s += '=='
    elif remainder == 3:
        s += '='
    import base64
    return base64.urlsafe_b64decode(s)

def create_token(payload: dict) -> str:
    header = {'alg': 'HS256', 'typ': 'JWT'}
    header_b64 = b64url_encode(json.dumps(header, separators=(',', ':')).encode())
    payload_b64 = b64url_encode(json.dumps(payload, separators=(',', ':')).encode())
    signing_input = f"{header_b64}.{payload_b64}"
    sig = hmac.new(SECRET_KEY.encode(), signing_input.encode(), hashlib.sha256).digest()
    sig_b64 = b64url_encode(sig)
    return f"{signing_input}.{sig_b64}"

def verify_token(token: str) -> dict:
    """Verify JWT token signature and claims."""
    if not token or not isinstance(token, str):
        return None

    parts = token.split('.')
    if len(parts) != 3:
        return None

    header_b64, payload_b64, sig_b64 = parts

    # Decode and validate header
    try:
        header = json.loads(b64url_decode(header_b64))
    except (json.JSONDecodeError, Exception):
        return None

    if header.get('alg') != 'HS256' or header.get('typ') != 'JWT':
        return None

    # Verify signature
    signing_input = f"{header_b64}.{payload_b64}"
    expected_sig = hmac.new(SECRET_KEY.encode(), signing_input.encode(), hashlib.sha256).digest()

    try:
        provided_sig = b64url_decode(sig_b64)
    except Exception:
        return None

    if not hmac.compare_digest(expected_sig, provided_sig):
        return None

    # Decode payload
    try:
        payload = json.loads(b64url_decode(payload_b64))
    except (json.JSONDecodeError, Exception):
        return None

    # Check expiration
    if payload.get('exp', 0) < time.time():
        return None

    return payload

# Rate limiting with sliding window
_rate_limits = {}
_RATE_WINDOW = 60
_RATE_MAX = 100

def check_rate_limit(client_ip: str) -> bool:
    now = time.time()
    if client_ip not in _rate_limits:
        _rate_limits[client_ip] = []
    # Clean old entries
    _rate_limits[client_ip] = [t for t in _rate_limits[client_ip] if now - t < _RATE_WINDOW]
    if len(_rate_limits[client_ip]) >= _RATE_MAX:
        return False
    _rate_limits[client_ip].append(now)
    return True

class APIHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        client_ip = self.client_address[0]
        if not check_rate_limit(client_ip):
            self._send_json(429, {'error': 'rate limited'})
            return

        if self.path == '/api/protected':
            self._handle_protected()
        elif self.path == '/api/health':
            self._send_json(200, {'status': 'ok'})
        else:
            self._send_json(404, {'error': 'not found'})

    def do_POST(self):
        client_ip = self.client_address[0]
        if not check_rate_limit(client_ip):
            self._send_json(429, {'error': 'rate limited'})
            return

        if self.path == '/api/login':
            self._handle_login()
        else:
            self._send_json(404, {'error': 'not found'})

    def _handle_login(self):
        try:
            content_len = int(self.headers.get('Content-Length', '0'))
            if content_len > 4096:
                self._send_json(413, {'error': 'too large'})
                return
            body = json.loads(self.rfile.read(content_len))
        except (ValueError, json.JSONDecodeError):
            self._send_json(400, {'error': 'invalid request'})
            return

        username = body.get('username', '')
        password = body.get('password', '')

        if not re.match(r'^[a-zA-Z0-9_]{1,32}$', username):
            self._send_json(400, {'error': 'invalid username'})
            return

        # Demo: accept any valid-format credentials
        token = create_token({
            'sub': username,
            'role': 'user',
            'exp': int(time.time()) + 3600
        })
        self._send_json(200, {'token': token})

    def _handle_protected(self):
        auth = self.headers.get('Authorization', '')
        if not auth.startswith('Bearer '):
            self._send_json(401, {'error': 'unauthorized'})
            return

        token = auth[7:]
        payload = verify_token(token)
        if not payload:
            self._send_json(401, {'error': 'invalid token'})
            return

        self._send_json(200, {'message': f"Hello {payload.get('sub')}", 'role': payload.get('role')})

    def _send_json(self, status: int, data: dict):
        body = json.dumps(data).encode()
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(body)))
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.end_headers()
        self.wfile.write(body)

if __name__ == '__main__':
    server = HTTPServer(('127.0.0.1', 8080), APIHandler)
    server.serve_forever()
